        for(auto tool:{core::Tool::CurvedArrow,core::Tool::Pen,core::Tool::Text,core::Tool::Select}){const UINT command=EditorToolFirst+static_cast<UINT>(tool);page->moreMenuAudit_=[command](CMenu&){return command;};page->SendMessage(WM_COMMAND,More);check(page->style_.tool==tool,"native More tool choices reach the WM_COMMAND tool handler instead of the generic action handler");}
        const auto revision=page->revision_;const auto base=page->document_.State().base;page->moreMenuAudit_=[](CMenu&){return UINT{Exit};};page->SendMessage(WM_COMMAND,More);page->moreMenuAudit_=[](CMenu&){return UINT{More};};page->SendMessage(WM_COMMAND,More);check(page->revision_==revision&&::IsWindow(main->m_hWnd),"More rejects non-editor and recursive/stale menu results");page->moreMenuAudit_={};
