        auto cleanup=[&]{layoutTestDpi=0;if(::IsWindow(workspaceWindow))workspace->SendMessage(WM_CLOSE);if(::IsWindow(mainWindow))main->DestroyWindow();AfxGetApp()->m_pMainWnd=previous;CString ignored;config.Save(original,ignored);services::PumpNativeTestMessages();};
